import{_ as e,o as d,c,a5 as t}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"计算机基础知识","description":"","frontmatter":{"title":"计算机基础知识","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/计算机基础知识.md","filePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/计算机基础知识.md"}'),s={name:"posts/java快速入门/第一部分：语言基础/01-基础语法/计算机基础知识.md"};function a(r,o,p,n,i,l){return d(),c("div",null,[...o[0]||(o[0]=[t("<div><p><strong>二进制</strong> 计算机中的数据不同于人们生活中的数据，人们生活采用十进制数，而计算机中全部采用二进制数表示，它只包含</p><p><code>0</code></p><p>、<code>1</code>两个数，逢二进一，<code>1+1=10</code>。每一个<code>0</code>或者每一个<code>1</code>，叫做一个<code>bit</code>（比特）。 下面了解一下十进制和二进制数据之间的转换计算。</p><ul><li>**十进制数据转成二进制数据：**使用除以<code>2</code>获取余数的方式</li><li>二进制数据转成十进制数据：使用<code>8421</code>编码的方式</li></ul><p>小贴士： 二进制数系统中，每个<code>0</code>或<code>1</code>就是一个位，叫做<code>bit</code>（比特）。</p><p><strong>字节</strong> 字节是我们常见的计算机中最小存储单元。计算机存储任何的数据，都是以字节的形式存储，右键点击文件属性， 我们可以查看文件的字节大小。</p><p><code>8</code></p><p>个<code>bit</code>（二进制位） <code>0000-0000</code>表示为<code>1</code>个字节，写成<code>1 byte</code>或者<code>1 B</code>。</p><ul><li>8 bit = 1 B</li><li>1024 B =1 KB</li><li>1024 KB =1 MB</li><li>1024 MB =1 GB</li><li>1024 GB = 1 TB</li></ul><p><strong>常用</strong><code>DOS</code><strong>命令</strong></p><p><code>Java</code></p><p>语言的初学者，学习一些<code>DOS</code>命令，会非常有帮助。<code>DOS</code>是一个早期的操作系统，现在已经被<code>Windows</code>系统取 代，对于我们开发人员，目前需要在<code>DOS</code>中完成一些事情，因此就需要掌握一些必要的命令。</p><p><strong>进入</strong><code>DOS</code><strong>操作窗口</strong> 按下<code>Windows+R</code>键盘，打开运行窗口，输入<code>cmd</code>回车，进入到<code>DOS</code>的操作窗口。 打开<code>DOS</code>命令行后，看到一个路径 <code>c:\\user</code> 就表示我们现在操作的磁盘是<code>c</code>盘。</p><p><strong>常用命令</strong><strong>命令</strong> <strong>操作符号</strong> 盘符切换命令 盘符名<code>:</code> 查看当前文件夹 <code>dir</code> 进入文件夹命令 <code>cd</code> 文件夹名 退出文件夹命令 <code>cd..</code> 退出到磁盘根目录 <code>cd\\</code> 清屏 <code>cls</code></p></div>",1)])])}const B=e(s,[["render",a]]);export{g as __pageData,B as default};
